"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Tabs: generated by UIX from the design system. Same variants and sizes as the Figma component.

const tabsListVariants = cva(
  "",
  {
    variants: {
      appearance: {
        underline: "flex gap-6 border-b border-line-default",
        pill: "inline-flex gap-1",
        boxed: "inline-flex gap-2",
      },
    },
    defaultVariants: {
      appearance: "underline",
    },
  },
);

const tabsTriggerVariants = cva(
  "inline-flex cursor-pointer items-center justify-center whitespace-nowrap transition-colors gap-2 text-label-medium [&_svg]:size-4 [&_svg]:shrink-0 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:pointer-events-none disabled:text-fg-disabled rounded-md",
  {
    variants: {
      appearance: {
        underline: "skin-quiet px-1 py-[10px] -mb-px border-b-2 border-transparent text-fg-secondary hover:text-fg-primary hover:border-line-strong aria-selected:text-fg-brand aria-selected:border-line-brand disabled:hover:border-transparent",
        pill: "skin-quiet px-3 py-1-5 text-fg-secondary hover:bg-muted hover:text-fg-primary aria-selected:bg-surface aria-selected:text-fg-primary aria-selected:shadow-sm aria-selected:hover:bg-surface",
        boxed: "px-4 py-[10px] border border-line-default text-fg-secondary hover:bg-subtle hover:text-fg-primary aria-selected:bg-brand aria-selected:text-fg-on-brand aria-selected:border-transparent aria-selected:hover:bg-brand aria-selected:hover:text-fg-on-brand",
      },
    },
    compoundVariants: [
      { appearance: "underline", class: "rounded-none" },
    ],
    defaultVariants: {
      appearance: "underline",
    },
  },
);

type TabsContextValue = {
  value: string;
  onValueChange: (value: string) => void;
  baseId: string;
  appearance: VariantProps<typeof tabsTriggerVariants>["appearance"];
};

const TabsContext = React.createContext<TabsContextValue | null>(null);

function useTabs() {
  const ctx = React.useContext(TabsContext);
  if (!ctx) throw new Error("Tabs parts must be used inside <Tabs>");
  return ctx;
}

export interface TabsProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof tabsTriggerVariants> {
  value: string;
  onValueChange: (value: string) => void;
}

const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(
  ({ className, value, onValueChange, appearance, ...props }, ref) => {
    const baseId = React.useId();
    return (
      <TabsContext.Provider value={{ value, onValueChange, baseId, appearance }}>
        <div ref={ref} data-slot="tabs" data-kind="control" className={cn("skin-quiet flex flex-col gap-4", className)} {...props} />
      </TabsContext.Provider>
    );
  },
);
Tabs.displayName = "Tabs";

const TabsList = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, onKeyDown, ...props }, ref) => {
  const { appearance } = useTabs();
  return (
    <div
      ref={ref}
      role="tablist"
      className={cn(tabsListVariants({ appearance }), className)}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        const tabs = Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]:not(:disabled)'));
        const index = tabs.indexOf(document.activeElement as HTMLButtonElement);
        if (index < 0) return;
        const last = tabs.length - 1;
        const next = event.key === "ArrowRight" ? (index === last ? 0 : index + 1) : event.key === "ArrowLeft" ? (index === 0 ? last : index - 1) : event.key === "Home" ? 0 : event.key === "End" ? last : -1;
        if (next < 0) return;
        event.preventDefault();
        tabs[next].focus();
        tabs[next].click();
      }}
      {...props}
    />
  );
});
TabsList.displayName = "TabsList";

export interface TabsTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
  /** Icon before the label. */
  leadingIcon?: React.ReactNode;
  /** Number pill after the label. */
  count?: React.ReactNode;
}

const TabsTrigger = React.forwardRef<HTMLButtonElement, TabsTriggerProps>(({ className, value, onClick, leadingIcon, count, children, ...props }, ref) => {
  const ctx = useTabs();
  const selected = ctx.value === value;
  return (
    <button
      ref={ref}
      type="button"
      role="tab"
      data-kind="control"
      id={ctx.baseId + "-tab-" + value}
      aria-selected={selected}
      aria-controls={ctx.baseId + "-panel-" + value}
      tabIndex={selected ? 0 : -1}
      className={cn(tabsTriggerVariants({ appearance: ctx.appearance }), className)}
      onClick={(event) => {
        onClick?.(event);
        ctx.onValueChange(value);
      }}
      {...props}
    >
      {leadingIcon}
      {children}
      {count != null ? <span className="inline-flex min-w-5 items-center justify-center rounded-full bg-current/15 px-1-5 text-label-small">{count}</span> : null}
    </button>
  );
});
TabsTrigger.displayName = "TabsTrigger";

export interface TabsContentProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
}

const TabsContent = React.forwardRef<HTMLDivElement, TabsContentProps>(({ className, value, ...props }, ref) => {
  const ctx = useTabs();
  return (
    <div
      ref={ref}
      role="tabpanel"
      id={ctx.baseId + "-panel-" + value}
      aria-labelledby={ctx.baseId + "-tab-" + value}
      hidden={ctx.value !== value}
      tabIndex={0}
      className={cn("focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus", className)}
      {...props}
    />
  );
});
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants, tabsTriggerVariants };
